t/public/audio/sets/7071/noun1_daniel_db97cf02.m4a", "voice": "male", "word": "a crown", "x": 0.8, "y": 0.27}, {"audio_url": "https://abyrutykpvmzkfbesire.supabase.co/storage/v1/object/public/audio/sets/7071/noun2_daniel_ec6e58c9.m4a", "voice": "male", "word": "a duke", "x": 0.5, "y": 0.44}, {"audio_url": "https://abyrutykpvmzkfbesire.supabase.co/storage/v1/object/public/audio/sets/7071/noun3_daniel_aaf25340.m4a", "voice": "male", "word": "a quad bike", "x": 0.62, "y": 0.66}, {"audio_url": "https://abyrutykpvmzkfbesire.supabase.co/storage/v1/object/public/audio/sets/7071/noun4_daniel_65d7dcad.m4a", "voice": "male", "word": "a puddle", "x": 0.4, "y": 0.85}]$a49$::jsonb, question = $a49$What is the duke doing?$a49$, answer_chips = $a49$["He", "is", "riding", "a", "quad bike", "through", "a", "puddle."]$a49$::jsonb, answer_text = $a49$He is riding a quad bike through a puddle.$a49$, answer_audio_url = $a49$https://abyrutykpvmzkfbesire.supabase.co/storage/v1/object/public/audio/sets/7071/answer_daniel_27f12bdd.m4a$a49$, tr = $a49${"cz": {"answer": "Jede na čtyřkolce přes louži.", "nouns": ["koruna", "vévoda", "čtyřkolka", "louže"], "phrases": ["nosit zlatou korunu", "valit se blátem", "odrážet šedou oblohu"], "question": "Co dělá vévoda?"}, "de": {"answer": "Er fährt mit einem Quad durch eine Pfütze.", "nouns": ["eine Krone", "ein Herzog", "ein Quad", "eine Pfütze"], "phrases": ["eine goldene Krone tragen", "durch den Schlamm rollen", "den grauen Himmel spiegeln"], "question": "Was macht der Herzog?"}, "es": {"answer": "Está cruzando un charco en un quad.", "nouns": ["una corona", "un duque", "un quad", "un charco"], "phrases": ["llevar una corona de oro", "rodar por el barro", "reflejar el cielo gris"], "question": "¿Qué está haciendo el duque?"}, "fr": {"answer": "Il traverse une flaque en quad.", "nouns": ["une couronne", "un duc", "un quad", "une flaque"], "phrases": ["porter une couronne en or", "rouler dans la boue", "refléter le ciel gris"], "question": "Que fait le duc ?"}, "hu": {"answer": "Quaddal hajt át egy pocsolyán.", "nouns": ["korona", "herceg", "quad", "pocsolya"], "phrases": ["egy aranykoronát viselni", "a sáron át gurulni", "a szürke eget tükrözni"], "question": "Mit csinál a herceg?"}, "sk": {"answer": "Ide na štvorkolke cez mláku.", "nouns": ["koruna", "vojvoda", "štvorkolka", "mláka"], "phrases": ["nosiť zlatú korunu", "valiť sa blatom", "odrážať sivú oblohu"], "question": "Čo robí vojvoda?"}, "tr": {"answer": "Bir su birikintisinin içinden ATV sürüyor.", "nouns": ["taç", "dük", "ATV", "su birikintisi"], "phrases": ["altın bir taç takmak", "çamurun içinden geçmek", "gri gökyüzünü yansıtmak"], "question": "Dük ne yapıyor?"}, "ua": {"answer": "Він їде на квадроциклі через калюжу.", "nouns": ["корона", "герцог", "квадроцикл", "калюжа"], "phrases": ["носити золоту корону", "котитися по багнюці", "відбивати сіре небо"], "question": "Що робить герцог?"}}$a49$::jsonb, content_version = 1, updated_at = $a49$2026-10-05 10:16:18.431557+00$a49$::timestamptz where media_id = 7071;
